sAppName: string, fullComponentName: string): Promise<LifeCycles> {\n36:   const poundIndex = fullComponentName.indexOf('#');\n37:   const isNamespaced = poundIndex >= 0;\n38:   const appName = isNamespaced ? fullComponentName.substring(0, poundIndex) : routesAppName;\n39:   const componentName = isNamespaced ? fullComponentName.substring(poundIndex + 1) : fullComponentName;\n40: \n41:   const module = await importDynamic<Module>(appName);\n42: \n43:   if (module && Object.hasOwn(module, componentName) && typeof module[componentName] === 'function') {\n44:     return initializeApp(appName, module).then(() => module[componentName]());\n45:   } else {\n46:     if (!module) {\n47:       console.warn(`Unknown app ${appName} for ${fullComponentName} defined in ${routesAppName}'s routes.json`);\n48:     } else if (module && Object.hasOwn(module, componentName)) {\n49:       console.warn(`The export ${fullComponentName}, defined in ${routesAppName}'s routes.json, is not a function`);\n50:     } else {\n51:       console.warn(\n52:         `${appName} does not define a component called \"${componentName}\", referenced in ${routesAppName}'s routes.json. This cannot be loaded.`,\n53:       );\n54:     }\n55:   }\n56: \n57:   return emptyLifecycle;\n58: }\n59: \n60: const emptyLifecycle: LifeCycles<never> = {\n61:   bootstrap() {\n62:     return Promise.resolve();\n63:   },\n64:   mount() {\n65:     return Promise.resolve();\n66:   },\n67:   unmount() {\n68:     return Promise.resolve();\n69:   },\n70: };\n71: \n72: /**\n73:  * This function can be used to manually initialize an application without waiting for the\n74:  * framework to load it. This can sometimes be helpful if the framework doesn't load code\n75:  * at the point you think is appropriate.\n76:  *\n77:  * This will ensure that the module is available and that it's `startupApp()` function (if\n78:  * any) will be called. Note that these are only guaranteed to be complete once the Promise\n79:  * returned from the function completes.\n80:  *\n81:  * @param appName The name of the app to initialize\n82:  * @param module The loaded code module, if available; if this parameter is omitted, this\n83:  *   function will load it.\n84:  * @returns a Promise which completes once the app has been loaded and initialized\n85:  */\n86: async function initializeApp(appName: string, module?: Module) {\n87:   if (!(appName in initializedApps)) {\n88:     let _module: Module = module ?? (await importDynamic<Module>(appName));\n89: \n90:     await (initializedApps[appName] = new Promise((resolve, reject) => {\n91:       if (Object.hasOwn(_module, 'startupApp')) {\n92:         const startup = _module['startupApp'];\n93:         if (typeof startup === 'function') {\n94:           return Promise.resolve(startup())\n95:             .then(() => {\n96:               registerModuleLoad(appName);\n97:               resolve(null);\n98:             })\n99:             .catch(reject);\n100:         }\n101:       }\n102: \n103:       registerModuleLoad(appName);\n104:       resolve(null);\n105:     }));\n106:   } else {\n107:     await initializedApps[appName];\n108:   }\n109: }\n110: \n\n(End of file - 110 lines total)\n</content>"}]}]},"parent_tool_use_id":null,"session_id":"3d5a2e85-6126-4015-bd02-07d3b380e2e8","uuid":"b359ffe0-5d6e-4b76-9bdd-fcf65f0f1799","timestamp":"2026-10-20T03:47:10.052Z","tool_use_result":[{"type":"text","text":"<repo>github.com/openmrs/openmrs-esm-core</repo>\n<path>packages/framework/esm-routes/src/loaders/load-lifecycles.ts</path>\n<url>undefined</url>\n<content>\n1: import { importDynamic } from '@openmrs/esm-dynamic-loading';\n2: import { type LifeCycles } from 'single-spa';\n3: import { registerModuleLoad } from '@openmrs/esm-config';\n4: \n5: // Couldn't figure out how to express this as an interface\n6: type Module = Omit<Record<string, () => LifeCycles | Promise<LifeCycles>>, 'startupApp'> & {\n7:   startupApp?: () => unknown;\n8: };\n9: \n10: /**\n11:  * @internal\n12: